{
  "units": [
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Subject to paragraph (2), an employee as defined by 5 U.S.C. 2105 or an individual employed by the government of the District of Columbia (whether permanent or temporary indefinite) is entitled to leave without loss in pay, time, or performance or efficiency rating for active duty, inactive-duty training (as defined in 37 U.S.C. 101), funeral honors duty (as described in 10 U.S.C. 12503 and 32 U.S.C. 115), or engaging in field or coast defense training under 32 U.S.C. 502–505 as a Reserve of the armed forces, a member of the National Guard, or a member of the Space Force in space force active status (as defined in 10 U.S.C. 101(e)(1)) and not on sustained duty under 10 U.S.C. 20105."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "threshold",
      "meaning": "Leave under 5 U.S.C. 6323(a) accrues for an employee or individual at the rate of 20 days per fiscal year and, to the extent not used in a fiscal year, accumulates for use in the succeeding fiscal year until it totals 20 days at the beginning of a fiscal year."
    },
    {
      "quote_ref": "F003",
      "scope_refs": ["F002"],
      "kind": "requirement",
      "meaning": "In the case of an employee or individual employed on a part-time career employment basis (as defined in 5 U.S.C. 3401(2)), the rate of leave accrual under 5 U.S.C. 6323(a) is a percentage of the rate prescribed under paragraph (1), determined by dividing 40 into the number of hours in the employee's or individual's regularly scheduled workweek during that fiscal year."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F002"],
      "kind": "threshold",
      "meaning": "The minimum charge for leave under 5 U.S.C. 6323(a) is one hour, and additional charges must be in multiples of one hour."
    },
    {
      "quote_ref": "F006:F016",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Except as provided by 5 U.S.C. 5519, an employee as defined by 5 U.S.C. 2105 or an individual employed by the government of the District of Columbia (permanent or temporary indefinite) who is a member of a Reserve component of the Armed Forces (10 U.S.C. 10101), the National Guard (32 U.S.C. 101), or the Space Force in space force active status (10 U.S.C. 101(e)(1)) and not on sustained duty under 10 U.S.C. 20105, and who performs either (A) service to provide military aid to enforce the law or assistance to civil authorities in protecting/saving life or property or preventing injury (via Federal service under 10 U.S.C. 331, 332, 333, 12406, or other applicable law, or full-time military service for a State, D.C., Puerto Rico, or a U.S. territory) or (B) full-time military service resulting from a call or order to active duty in support of a contingency operation (10 U.S.C. 101(a)(13)), is entitled during and because of such service to leave without loss of or reduction in pay, leave otherwise entitled, credit for time or service, or performance or efficiency rating, not to exceed 22 workdays in a calendar year."
    },
    {
      "quote_ref": "F016",
      "scope_refs": ["F006:F014"],
      "kind": "permission",
      "meaning": "Upon the request of an employee absent to perform service described in 5 U.S.C. 6323(b)(2), the period of absence may be charged to the employee’s accrued annual leave or available compensatory time instead of being charged as leave under subsection (b)."
    },
    {
      "quote_ref": "F016",
      "scope_refs": ["F006:F014"],
      "kind": "prohibition",
      "meaning": "The period for which an employee is absent to perform service described in 5 U.S.C. 6323(b)(2) may not be charged to sick leave."
    },
    {
      "quote_ref": "F017",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "An employee as defined by 5 U.S.C. 2105 or an individual employed by the government of the District of Columbia who is a member of the National Guard of the District of Columbia is entitled to leave without loss in pay or time for each day of a parade or encampment ordered or authorized under title 39, District of Columbia Code, covering each day of service the National Guard, or a portion thereof, is ordered to perform by the commanding general."
    },
    {
      "quote_ref": "F019",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "A military reserve technician described in 5 U.S.C. 8401(30) is entitled, at such person's request, to leave without loss of or reduction in pay, other entitled leave, credit for time or service, or performance or efficiency rating for each day (not to exceed 44 workdays in a calendar year) that such person is on active duty without pay pursuant to 10 U.S.C. 12315 under 10 U.S.C. 12301(b) or 12301(d) for participation in operations outside the United States, its territories, and possessions."
    },
    {
      "quote_ref": "F020",
      "scope_refs": ["F019"],
      "kind": "permission",
      "meaning": "An employee who requests annual leave or compensatory time to which the employee is otherwise entitled, for a period during which the employee would have been entitled upon request to leave under 5 U.S.C. 6323(d), may be granted such annual leave or compensatory time without regard to 5 U.S.C. 6323 or 5 U.S.C. 5519."
    },
    {
      "quote_ref": "F085:F092",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "During the current fiscal year and thereafter, funds appropriated or otherwise available for any Federal agency, Congress, the judicial branch, or the District of Columbia may be used for the pay, allowances, and benefits of an employee (5 U.S.C. 2105) or D.C. government employee (permanent or temporary indefinite) who is a member of a Reserve component of the Armed Forces or the National Guard, performs qualifying law enforcement or protective assistance military service, and requests and is granted leave under this section or annual leave (which may be granted without regard to 5 U.S.C. 5519 and 6323(b) if otherwise entitled)."
    },
    {
      "quote_ref": "F094",
      "scope_refs": ["F085:F092"],
      "kind": "requirement",
      "meaning": "Any employee who requests leave under subsection (3)(A) for service described in subsection (2) of section 8023 of Pub. L. 107–117 is entitled to such leave, subject to the provisions of that section and the last sentence of 5 U.S.C. 6323(b), and such leave shall be considered leave under 5 U.S.C. 6323(b)."
    },
    {
      "quote_ref": "F109",
      "scope_refs": [],
      "kind": "definition",
      "meaning": "Under Act July 1, 1947, ch. 192, § 4, the words 'officers and employees of the United States or of the District of Columbia' in specified prior provisions mean all officers and employees of the United States or D.C., permanent or temporary indefinite, without regard to civil service classifications or terminology, and include substitute employees in the postal field service, who are entitled to military leave of absence on the basis of 1 hour of leave for each 26 hours of work in the preceding calendar year, provided they worked at least 1,040 hours in that preceding year, with pay not to exceed 80 hours per calendar year."
    }
  ]
}
